// Nuclear facility reference data. Dependency-free in shared/ so the watched-site
// registry and its seeder can read the same table the map does.
// `src/config/geo-map.ts` re-exports it typed as the client `NuclearFacility`.

export type NuclearFacilityRecordType =
  | 'plant'
  | 'enrichment'
  | 'reprocessing'
  | 'weapons'
  | 'ssbn'
  | 'test-site'
  | 'icbm'
  | 'research';

export interface NuclearFacilityRecord {
  id: string;
  name: string;
  lat: number;
  lon: number;
  type: NuclearFacilityRecordType;
  status: 'active' | 'contested' | 'inactive' | 'decommissioned' | 'construction';
  /** ISO 3166-1 alpha-2 code of the operating country. */
  operator?: string;
  operationalSince?: string;
  treaties?: string[];
  iaeaStatus?: string;
  keyEvents?: string[];
}

